"use strict";
// Methods in a DYN object literal, driven end to end.
//
// `mk`'s parameter is untyped, so the argument literal's contextual type is
// `any` and the literal takes the JS declaration fallback — it builds as a
// dyn object rather than a record. That is the same road esbuild's
// `__commonJS` module table travels; this package reaches the entries by an
// explicit key instead of `Object.getOwnPropertyNames`, so the whole
// program is static and its stdout is a byte-for-byte claim against Node.
function mk(t) {
  return function (k) {
    return t[k];
  };
}

// plain shorthand methods, string-literal keys with characters no C
// identifier can spell
var op = mk({
  "op/double"(x) {
    return x * 2;
  },
  // `0 - x`, not `-x`: unary negation of an untyped value is a separate
  // gap (SC1043) this fixture is not about
  "op/negate"(x) {
    return 0 - x;
  },
  // the five varint groups of a uint32, unrolled — a method body that is
  // nothing but bitwise arithmetic on an untyped parameter
  "op/varint"(x) {
    var n = x >>> 0;
    return [n & 127, (n >>> 7) & 127, (n >>> 14) & 127, (n >>> 21) & 127, (n >>> 28) & 15].join(".");
  },
  // several parameters, and a closure over the enclosing scope
  "op/affine"(x, y) {
    return x * scale + y;
  },
  // zero parameters
  "op/tag"() {
    return "tag" + scale;
  },
  // a method whose body calls a SIBLING entry through the same table
  "op/twice"(x) {
    return op("op/double")(op("op/double")(x));
  },
});

var scale = 10;

// identifier keys and a NUMERIC key ride the same path
var num = mk({
  0: function (x) {
    return "zero:" + x;
  },
  named(x) {
    return "named:" + x;
  },
});

// evaluation ORDER: JS builds an object literal property by property, in
// source order. Methods create their closures in place, so a table built
// beside effectful property values must keep the interleaving.
var log = [];
var ordered = mk({
  a: (log.push("a"), 1),
  b(x) {
    log.push("b-called");
    return x;
  },
  c: (log.push("c"), 3),
});

module.exports = {
  double: function (x) {
    return op("op/double")(x);
  },
  negate: function (x) {
    return op("op/negate")(x);
  },
  varint: function (x) {
    return op("op/varint")(x);
  },
  affine: function (x, y) {
    return op("op/affine")(x, y);
  },
  tag: function () {
    return op("op/tag")();
  },
  twice: function (x) {
    return op("op/twice")(x);
  },
  zero: function (x) {
    return num("0")(x);
  },
  named: function (x) {
    return num("named")(x);
  },
  order: function (x) {
    var v = ordered("b")(x);
    return log.join(",") + "=" + v;
  },
};
